import json,numpy as np
from PIL import Image
m=json.load(open('/app/output/settled_meta.json'));cam=m['cameras']['wrist_right'];E=np.array(cam['extrinsic_cv']);K=np.array(cam['intrinsic_cv']);im=np.array(Image.open('/app/output/settled_wrist_right.png'));d=np.load('/app/output/settled_wrist_right_depth.npy');Y,X=np.indices(d.shape);pc=np.stack(((X-K[0,2])*d/K[0,0],(Y-K[1,2])*d/K[1,1],d),-1);pw=(pc-E[:,3])@E[:,:3]
red=(im[:,:,0]>im[:,:,1]*1.02)&(im[:,:,1]>im[:,:,2]*1.01)&(im[:,:,0]>20)&(d>0)&(pw[:,:,0]>.35)&(pw[:,:,0]<.6)&(pw[:,:,1]>-.2)&(pw[:,:,1]<.15)&(pw[:,:,2]>.75)
for xb in [(0.40,.42),(.42,.44),(.44,.46),(.46,.48),(.48,.50),(.50,.52)]:
 for zb in [(.79,.81),(.81,.83),(.83,.845)]:
  mm=red&(pw[:,:,0]>=xb[0])&(pw[:,:,0]<xb[1])&(pw[:,:,2]>=zb[0])&(pw[:,:,2]<zb[1]);ys=pw[:,:,1][mm]
  if len(ys)>10: print(xb,zb,len(ys),np.percentile(ys,[5,50,95]).round(3).tolist())
